using CustomGolfStats.Domain;

namespace CustomGolfStats.Api.Data.Entities;

/// <summary>
/// A golfer's round. <see cref="Id"/> is created on the device (never generated by the database).
/// The number of holes is the number of <see cref="HoleResults"/>.
/// </summary>
public class Round
{
    public Guid Id { get; set; }

    public Guid AccountId { get; set; }

    public Account Account { get; set; } = null!;

    public Guid TeeVersionId { get; set; }

    public TeeVersion TeeVersion { get; set; } = null!;

    public DateOnly PlayedOn { get; set; }

    public DateTimeOffset? StartedAt { get; set; }

    public DateTimeOffset? FinishedAt { get; set; }

    public EntryMode EntryMode { get; set; }

    public RoundType RoundType { get; set; } = RoundType.Casual;

    public string? Notes { get; set; }

    public string? WeatherConditions { get; set; }

    /// <summary>numeric(5,1).</summary>
    public decimal? TemperatureF { get; set; }

    /// <summary>numeric(5,1).</summary>
    public decimal? WindSpeedMph { get; set; }

    public int? WindDirectionDegrees { get; set; }

    /// <summary>Free-text weather from golftrack, for migrated rounds only.</summary>
    public string? LegacyWeather { get; set; }

    public int? DurationMinutes { get; set; }

    /// <summary>numeric(6,2).</summary>
    public decimal? DistanceMiles { get; set; }

    public int? StepCount { get; set; }

    /// <summary>When the device last edited the round; decides last-write-wins.</summary>
    public DateTimeOffset ClientUpdatedAt { get; set; }

    /// <summary>Server time of the last write (set by the server, never the client); drives <c>sync/changes</c>.</summary>
    public DateTimeOffset ModifiedAt { get; set; }

    /// <summary>Soft delete, so deletes sync.</summary>
    public DateTimeOffset? DeletedAt { get; set; }

    /// <summary>Optimistic concurrency counter: starts at 1, incremented on every server write.</summary>
    public int Version { get; set; } = 1;

    /// <summary>True once this round has used one of a Free golfer's trial shot-by-shot rounds.</summary>
    public bool TrialCounted { get; set; }

    public List<HoleResult> HoleResults { get; set; } = [];
}
